function ClickHandler() {
  const handleClick = () => alert('Button clicked!');

  return <button onClick={handleClick}>Click Me</button>;
}
```

```jsx
function Form() {
  const [name, setName] = useState('');

  return (
    <form>
      <input value={name} onChange={e => setName(e.target.value)} />
      <p>Hello, {name}</p>
    </form>
  );
}
```

